INSERT INTO faculty (id, email, password_hash, full_name, username, designation, department, institution, phone, office_location, office_hours, visiting_hours, address, bio, photo, resume_file, website, google_scholar, linkedin, is_detached, detached_at, github, research_summary, is_active, created_at) VALUES ('1', 'anand.kumar@university.edu', 'scrypt:32768:8:1$U4cnHJ8gkRWCC3jz$0f31ad0ed8e0f8d23e83bfb83213aa4bf3d6dd1bbe214ff144787b613b991ee051c65d5cf1f4c8f7bb3e6328ad5b4a6a802aa9835d8bcd29fb00721f2dbadb5d', 'Anand Kumar', 'anand', 'Professor', 'CSE', 'University', '', '', '', '', '', 'Dr. Anand Kumar is a Professor in the Department of Computer Science and Engineering with over 15 years of experience in teaching and research. His research interests span machine learning, data science, and intelligent systems. He has published extensively in top-tier conferences and journals.', 'ef2de2a5b38504ce_sample_image.jpg', '63c39668822cc8d3_ML_Queue_Management_Waiting_Time_Estimation_Project_Specification.pdf', '', 'https://scholar.google.com/citations?user=anand', 'https://linkedin.com/in/anand-kumar', '0', 'NULL', 'https://github.com/anand-kumar', '', '1', '2026-08-24 19:00:26');
