INSERT INTO research_interests (id, faculty_id, title, description, is_published) VALUES ('1', '1', 'Machine Learning and Deep Learning', 'Research on supervised and unsupervised learning algorithms, including neural network architectures for classification and regression tasks.', '1');
INSERT INTO research_interests (id, faculty_id, title, description, is_published) VALUES ('2', '1', 'Natural Language Processing', 'Computational linguistics, sentiment analysis, text classification, and language modeling using transformer architectures.', '1');
INSERT INTO research_interests (id, faculty_id, title, description, is_published) VALUES ('3', '1', 'Distributed Systems', 'Cloud computing, microservices architecture, and scalable distributed computing frameworks.', '1');
