INSERT INTO achievements (id, faculty_id, title, description, category, year, certificate_photo, is_published) VALUES ('1', '1', 'Best Paper Award - ICML 2022', 'Received Best Paper Award for "Efficient Transformer Architectures for Low-Resource NLP" at the International Conference on Machine Learning.', 'award', '2022', 'best_paper_award.svg', '1');
INSERT INTO achievements (id, faculty_id, title, description, category, year, certificate_photo, is_published) VALUES ('2', '1', 'INSA Young Scientist Award', 'Awarded by the Indian National Science Academy for outstanding contributions to computational linguistics.', 'award', '2019', '', '1');
INSERT INTO achievements (id, faculty_id, title, description, category, year, certificate_photo, is_published) VALUES ('3', '1', 'Oracle ACE Award 2023', 'Recognized by Oracle Corporation for contributions to cloud-native application development.', 'recognition', '2023', 'aws_certificate.svg', '1');
INSERT INTO achievements (id, faculty_id, title, description, category, year, certificate_photo, is_published) VALUES ('4', '1', 'DST Early Career Research Award', 'Department of Science and Technology grant for research in federated learning systems.', 'grant', '2017', '', '1');
INSERT INTO achievements (id, faculty_id, title, description, category, year, certificate_photo, is_published) VALUES ('5', '1', 'Fellowship - Indian Society for Technical Education', 'Elected Fellow of ISTE for significant contributions to engineering education.', 'fellowship', '2021', '', '1');
INSERT INTO achievements (id, faculty_id, title, description, category, year, certificate_photo, is_published) VALUES ('6', '1', 'Google Research Award', 'Collaborative research grant for work on multilingual NLP systems.', 'grant', '2020', '', '1');
INSERT INTO publications (id, faculty_id, title, authors, journal, year, doi, url, abstract, pub_type, is_published) VALUES ('1', '1', 'Efficient Transformer Architectures for Low-Resource NLP', 'A. Kumar, R. Singh, P. Sharma', 'Proceedings of ICML', '2022', '10.1109/icml.2022.12345', 'https://doi.org/10.1109/icml.2022.12345', 'We propose a novel transformer architecture that achieves comparable performance to large language models while using 60% fewer parameters. Our approach leverages adaptive attention mechanisms and sparse connectivity patterns to reduce computational overhead while maintaining accuracy on standard NLP benchmarks.', 'conference', '1');
INSERT INTO publications (id, faculty_id, title, authors, journal, year, doi, url, abstract, pub_type, is_published) VALUES ('2', '1', 'Deep Learning Approaches for Sentiment Analysis in Hindi Text', 'A. Kumar, M. Gupta', 'Journal of Natural Language Processing', '2021', '10.1016/j.nlp.2021.67890', 'https://doi.org/10.1016/j.nlp.2021.67890', 'This paper presents a comprehensive study of deep learning methods for sentiment analysis in Hindi, a low-resource language. We introduce a new annotated dataset and demonstrate that transfer learning from English models with language-adaptive fine-tuning achieves state-of-the-art results.', 'journal', '1');
INSERT INTO publications (id, faculty_id, title, authors, journal, year, doi, url, abstract, pub_type, is_published) VALUES ('3', '1', 'Federated Learning for Privacy-Preserving Medical Data Analysis', 'A. Kumar, S. Patel, K. Venkatesh', 'IEEE Transactions on Medical Imaging', '2020', '10.1109/tmi.2020.30123', 'https://doi.org/10.1109/tmi.2020.30123', 'We present a federated learning framework that enables collaborative training of medical imaging models across multiple hospitals without sharing raw patient data. Our method achieves 95% of the centralized model accuracy while providing formal differential privacy guarantees.', 'journal', '1');
INSERT INTO publications (id, faculty_id, title, authors, journal, year, doi, url, abstract, pub_type, is_published) VALUES ('4', '1', 'Scalable Microservices Architecture for Real-Time Data Processing', 'A. Kumar, V. Mehta', 'ACM Computing Surveys', '2019', '10.1145/3312345', 'https://doi.org/10.1145/3312345', 'A comprehensive survey of microservices architectures for real-time data processing systems. We analyze 25 production deployments and propose a reference architecture pattern that addresses common challenges in scalability, fault tolerance, and data consistency.', 'journal', '1');
INSERT INTO courses (id, faculty_id, name, code, description, semester, schedule, is_published) VALUES ('1', '1', 'Machine Learning', 'CS401', 'Introduction to machine learning algorithms, supervised and unsupervised learning, neural networks, evaluation metrics, and practical implementation using Python and scikit-learn.', 'Odd Semester 2024-25', 'Mon-Wed 10:00-11:30 AM', '1');
INSERT INTO courses (id, faculty_id, name, code, description, semester, schedule, is_published) VALUES ('2', '1', 'Natural Language Processing', 'CS502', 'Advanced course covering text processing, language modeling, named entity recognition, sentiment analysis, and modern transformer-based approaches to NLP.', 'Even Semester 2024-25', 'Tue-Thu 2:00-3:30 PM', '1');
